/**
 * Web Push (free; no third-party service). Keys come from Vercel env vars
 * WEB_PUSH_VAPID_PUBLIC_KEY / WEB_PUSH_VAPID_PRIVATE_KEY, generated by hannah on
 * her Mac with `npx web-push generate-vapid-keys`. Until both are set,
 * isConfigured() is false and nothing is sent; alerts still land in history.
 */

const webpush = require('web-push');
const pool = require('../../db/pool');
const logger = require('../../utils/logger');

const SUBJECT = process.env.WEB_PUSH_SUBJECT || 'https://www.muse.shopping';
// Drop a device after this many failed sends in a row (410/404 drop it at once).
const MAX_FAILURES = 5;

let configuredWith = null;
function isConfigured() {
  const pub = process.env.WEB_PUSH_VAPID_PUBLIC_KEY;
  const priv = process.env.WEB_PUSH_VAPID_PRIVATE_KEY;
  if (!pub || !priv) return false;
  if (configuredWith !== pub) {
    try {
      webpush.setVapidDetails(SUBJECT, pub, priv);
      configuredWith = pub;
    } catch (err) {
      logger.warn(`Push: VAPID keys rejected: ${err.message}`);
      return false;
    }
  }
  return true;
}

function publicKey() {
  return process.env.WEB_PUSH_VAPID_PUBLIC_KEY || null;
}

async function saveSubscription(userId, sub, userAgent) {
  const endpoint = sub && sub.endpoint;
  const keys = (sub && sub.keys) || {};
  if (typeof endpoint !== 'string' || !/^https:\/\//.test(endpoint) || endpoint.length > 2000) {
    throw Object.assign(new Error('invalid push endpoint'), { statusCode: 400 });
  }
  if (typeof keys.p256dh !== 'string' || typeof keys.auth !== 'string' || keys.p256dh.length > 500 || keys.auth.length > 200) {
    throw Object.assign(new Error('invalid push keys'), { statusCode: 400 });
  }
  // A device belongs to whoever signed in on it last.
  await pool.query(
    `INSERT INTO push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
     VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (endpoint) DO UPDATE
       SET user_id = EXCLUDED.user_id, p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth,
           user_agent = EXCLUDED.user_agent, failure_count = 0`,
    [userId, endpoint, keys.p256dh, keys.auth, String(userAgent || '').slice(0, 300)],
  );
}

async function removeSubscription(userId, endpoint) {
  await pool.query('DELETE FROM push_subscriptions WHERE user_id = $1 AND endpoint = $2', [userId, endpoint]);
}

async function countDevices(userId) {
  const { rows } = await pool.query('SELECT COUNT(*)::int AS n FROM push_subscriptions WHERE user_id = $1', [userId]);
  return rows[0] ? rows[0].n : 0;
}

/**
 * Send one payload to every device of a shopper.
 * Returns { devices, delivered }.
 */
async function sendToUser(userId, payload) {
  if (!isConfigured()) return { devices: 0, delivered: 0, configured: false };
  const { rows: subs } = await pool.query(
    'SELECT id, endpoint, p256dh, auth FROM push_subscriptions WHERE user_id = $1', [userId],
  );
  let delivered = 0;
  const body = JSON.stringify(payload);
  await Promise.all(subs.map(async s => {
    try {
      await webpush.sendNotification(
        { endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
        body,
        { TTL: 60 * 60 * 12, urgency: 'normal' },
      );
      delivered += 1;
      await pool.query('UPDATE push_subscriptions SET last_success_at = now(), failure_count = 0 WHERE id = $1', [s.id]);
    } catch (err) {
      const gone = err.statusCode === 404 || err.statusCode === 410;
      logger.warn(`Push: send to device ${s.id} failed (${err.statusCode || err.message})`);
      if (gone) {
        await pool.query('DELETE FROM push_subscriptions WHERE id = $1', [s.id]);
      } else {
        await pool.query(
          'UPDATE push_subscriptions SET failure_count = failure_count + 1 WHERE id = $1', [s.id],
        );
        await pool.query('DELETE FROM push_subscriptions WHERE id = $1 AND failure_count >= $2', [s.id, MAX_FAILURES]);
      }
    }
  }));
  return { devices: subs.length, delivered, configured: true };
}

module.exports = { isConfigured, publicKey, saveSubscription, removeSubscription, countDevices, sendToUser };
